 rating:[['platform','评分平台','select',{steam:'Steam推荐比例',heybox:'小黑盒十分制',metacritic:'Metacritic',other:'其他'}],['scope','统计范围（Steam默认matching_query_summary）'],['observed_at','统计时刻（ISO含时区）'],['positive','推荐数（Steam）','number'],['negative','不推荐数（Steam）','number'],['total_reviews','同口径总评价数（Steam）','number'],['filters.language','评论语言（all / schinese等）'],['filters.review_type','Steam评论类型','select',{all:'全部评价（共同分母）'}],['filters.purchase_type','Steam购买口径','select',{steam:'Steam购买',all:'所有购买来源',non_steam_purchase:'非Steam购买'}],['filters.filter_offtopic_activity','是否过滤跑题活动','select',{'1':'过滤','0':'不排除'}],['scale','非Steam评分量表（如0–10）'],['sample_size','非Steam评价样本量','number']],
 quote:[['quote_mode','引用形式','select',{direct:'原文直引',translation:'译文',paraphrase:'概述'}],['original_date','原始访谈日期'],['original_text','对应的原文短片段','area']],
 role:[['person','制作人姓名'],['work','具体作品'],['role','此作品中的职务'],['as_of','职务来源日期']],
